{
  "conflicts": [
    {
      "id": "CONFLICT-001",
      "claim_ids": ["CLM-001-0006", "CLM-001-0013"],
      "question": "当会员卡的权益开始日（valid_from）落在自然月月底当天时，当月该账户是否计入月末有资格账户并将其当月订单纳入统计？王经理表示口径为先按月末最后一天选拔有资格账户，再统计其当月全渠道/全门店有效订单（不要求订单发生当天具备资格）；而小林提出并非一律按月末有资格算，已知规则要求“月末才生效但当月此前有购买的账户”才纳入当月有效购买，需要核实此前是否有购买记录。两方在资格与订单纳入口径的前提条件上存在差异。",
      "next_step": "由运营牵头（小林）与统计口径核查人（王经理）进行对齐，明确“月底当天生效”与“当月此前订单计入”的具体业务判定规则并形成书面确认。"
    },
    {
      "id": "CONFLICT-002",
      "claim_ids": ["CLM-001-0011", "CLM-001-0014", "CLM-002-0017"],
      "question": "会员卡的权益结束日（valid_until）或提前终止日（ended_at）落在月底当天时，该账户在当天是否算有效付费会员？运营小林认为自身无法判断、属于未决事项，转介给IT老周核实系统记录；而IT周工表示自己不掌握判定细节，不能凭日期写法下结论，需要先由小林确认会员范围，再核对系统统计说明并结合实际资格记录判断，双方在问题判断的责任归属和记录来源上存在转介闭环/未决。",
      "next_step": "由运营小林与IT老周共同会商，小林先书面明确业务端对结束日/终止日边界的口径定义，周工再结合系统数据结构和实际记录核对能否支撑，形成统一的书面规则。"
    }
  ]
}
